/**
 * Tier: ACTION (requires the `tabCapture` optional permission).
 *
 * `record_tab_video` records video (and optional audio) of a tab via
 * chrome.tabCapture + MediaRecorder. The MediaRecorder lives in the
 * offscreen document; this handler is a thin SW-side coordinator that
 * resolves a stream id, drives the offscreen recorder via VIDEO_RUN,
 * waits for the encoded blob, and uploads it to cld_files.
 *
 * Returns:
 *   { ok: true, file_id, file_url, mime_type, duration_ms, size_bytes,
 *     width: null, height: null }     // dimensions resolved by the server
 *
 * Or, on a declared error condition (permission missing, source declined,
 * MediaRecorder error, upload failure):
 *   { ok: false, reason, remediation? }
 *
 * Not admin-gated — gated only by the `tabCapture` optional permission
 * (tl_def.admin_only=false is the source of truth; see the 2026-05 drift
 * reconciliation that removed admin_only from all advertised capture/CDP
 * tools to match the DB).
 */

import { uploadFile } from '@/lib/api/routes/files';
import { getAssignedTabId } from '@/lib/tools/handlers/_active-tab';
import type { ToolHandler } from '@/lib/tools/types';
import { runVideoCapture } from '@/lib/video/video-sw';
import { z } from 'zod';

const RecordTabVideoArgs = z.object({
  /**
   * How long to record, in milliseconds. Capped at 60_000 to keep upload
   * payloads bounded — recordings beyond a minute are better orchestrated
   * via repeated calls or a future dedicated long-form path.
   */
  duration_ms: z.number().int().positive().max(60_000).optional().default(5_000),
  /** Capture audio along with video. Default false. */
  audio: z.boolean().optional().default(false),
  /**
   * Tab to capture. Defaults to the agent's assigned tab when omitted —
   * the same fallback rule as every other action-tier tool.
   */
  tab_id: z.number().int().optional(),
  /**
   * Optional logical filename. If omitted, derived from the tab title.
   * The cld_files path defaults to `browser-agent/recordings/<filename>`.
   */
  filename: z.string().optional(),
});
type RecordTabVideoArgs = z.infer<typeof RecordTabVideoArgs>;

function sanitizeFilename(input: string): string {
  return (
    input
      .replace(/[�-]/g, '')
      .replace(/[\\/:*?"<>|]/g, '-')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 100) || 'recording'
  );
}

function extensionFor(mimeType: string): string {
  if (mimeType.startsWith('video/webm')) return 'webm';
  if (mimeType.startsWith('video/mp4')) return 'mp4';
  return 'webm';
}

export const record_tab_video: ToolHandler<RecordTabVideoArgs, unknown> = {
  name: 'chrome_record_tab_video',
  tier: 'action',
  required_optional_permissions: ['tabCapture'],
  supportedBrowsers: ['chrome'],
  argsSchema: RecordTabVideoArgs,
  run: async (args, ctx) => {
    let targetTabId: number | null | undefined = args.tab_id;
    if (targetTabId == null) {
      targetTabId = await getAssignedTabId(ctx);
    }
    if (targetTabId == null) {
      return { ok: false, reason: 'No tab to record' };
    }

    // The dispatcher already gated `tabCapture` permission; if we got here
    // the toggle is on. Defense-in-depth: also verify the API exists.
    if (!chrome.tabCapture?.getMediaStreamId) {
      return {
        ok: false,
        reason: 'tabCapture API unavailable',
        remediation: 'Enable Settings → Advanced → Tab video capture.',
      };
    }

    const result = await runVideoCapture({
      targetTabId,
      audio: args.audio,
      durationMs: args.duration_ms,
    });

    if (!result.ok || !result.data) {
      return {
        ok: false,
        reason: result.reason ?? 'recording failed with no further detail',
      };
    }

    if (result.sizeBytes === 0) {
      return {
        ok: false,
        reason: 'recording produced zero bytes',
      };
    }

    const ext = extensionFor(result.mimeType ?? 'video/webm');
    let baseName: string;
    if (args.filename) {
      baseName = sanitizeFilename(args.filename);
      if (!baseName.toLowerCase().endsWith(`.${ext}`)) baseName += `.${ext}`;
    } else {
      try {
        const tab = await chrome.tabs.get(targetTabId).catch(() => null);
        const titleBase = tab?.title ? sanitizeFilename(tab.title) : 'tab';
        baseName = `${titleBase}-${Date.now()}.${ext}`;
      } catch {
        baseName = `tab-${Date.now()}.${ext}`;
      }
    }

    // Reuse the existing cld_files upload helper — same path the screenshot
    // and record_gif handlers use. Keeps the agent's referenceable artifact
    // set in one place.
    const buffer = new ArrayBuffer(result.data.byteLength);
    new Uint8Array(buffer).set(new Uint8Array(result.data));
    const blob = new Blob([buffer], { type: result.mimeType ?? 'video/webm' });

    let upload: { file_id: string; url: string | null; cdn_url: string | null };
    try {
      upload = await uploadFile(blob, baseName, {
        path: `browser-agent/recordings/${baseName}`,
        metadata: {
          source: 'tab_capture',
          duration_ms: result.durationMs,
          audio: result.audio,
          tab_id: targetTabId,
        },
      });
    } catch (err) {
      return {
        ok: false,
        reason: `upload failed: ${(err as Error).message}`,
        captured_bytes: result.sizeBytes,
        duration_ms: result.durationMs,
      };
    }

    const fileUrl = upload.url ?? upload.cdn_url ?? null;
    return {
      ok: true,
      file_id: upload.file_id,
      file_url: fileUrl,
      mime_type: result.mimeType,
      duration_ms: result.durationMs,
      size_bytes: result.sizeBytes,
      audio: result.audio,
      source: result.source,
    };
  },
};

export const video_handlers = [record_tab_video];
