import {
  ConfirmDialogHost,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
  TooltipProvider,
} from '@ai-matrx/design-system';
import {
  BookOpen,
  Bug,
  Calendar,
  Camera,
  Crosshair,
  Database,
  Files,
  Highlighter,
  Inbox,
  KeyRound,
  Library,
  ListChecks,
  ListTodo,
  Loader2,
  MessageSquare,
  NotebookPen,
  ScanLine,
  Search,
  Settings as SettingsIcon,
  Sparkles,
  Vault,
  Wrench,
} from 'lucide-react';
import { type ComponentType, Suspense, lazy, useEffect, useRef, useState } from 'react';

// Per-tab dynamic imports. Single source of truth for module paths so each
// view ships in its own chunk and the eager sidepanel bundle stays small.
// Used both as the loader for `lazy()` and to pre-warm the chunk on tab
// change (browsers + Vite dedupe identical `import()` calls, so calling the
// loader twice doesn't double-fetch).
// Annotated, not `satisfies`: `satisfies` keeps each entry's *inferred* type,
// which contextual typing widens to `{ default: () => JSX.Element } | { default: ComponentType }`.
// `lazy()` can't pick a component type out of that union (TS7 rejects it).
const VIEW_LOADERS: Record<SidepanelTab, () => Promise<{ default: ComponentType }>> = {
  // W2 in progress: `sidepanel.html?chat=package` mounts the shared @ai-matrx/chat; the
  // extension's own chat stays the default until the package renders every piece it needs
  // in this host (no stand-ins), then this switch and ChatView are deleted together.
  chat: () =>
    new URLSearchParams(location.search).get('chat') === 'package'
      ? import('@/features/package-chat/PackageChatView').then((m) => ({
          default: m.PackageChatView,
        }))
      : import('@/features/chat/ChatView').then((m) => ({ default: m.ChatView })),
  pilot: () => import('@/features/chat/PilotView').then((m) => ({ default: m.PilotView })),
  tasks: () => import('@/features/tasks/TasksView').then((m) => ({ default: m.TasksView })),
  lists: () => import('@/features/lists/ListsHubView').then((m) => ({ default: m.ListsHubView })),
  agenda: () => import('@/features/agenda/AgendaView').then((m) => ({ default: m.AgendaView })),
  scrape: () => import('@/features/scrape/ScrapeView').then((m) => ({ default: m.ScrapeView })),
  'saved-captures': () =>
    import('@/features/saved-captures/SavedCapturesView').then((m) => ({
      default: m.SavedCapturesView,
    })),
  capture: () =>
    import('@/features/capture-ladder/NeedsYourBrowserView').then((m) => ({
      default: m.NeedsYourBrowserView,
    })),
  data: () => import('@/features/data/DataView').then((m) => ({ default: m.DataView })),
  highlight: () =>
    import('@/features/highlights/HighlightView').then((m) => ({ default: m.HighlightView })),
  guidance: () =>
    import('@/features/guidance/GuidanceView').then((m) => ({ default: m.GuidanceView })),
  seo: () => import('@/features/seo/SeoView').then((m) => ({ default: m.SeoView })),
  notes: () => import('@/features/notes/NotesView').then((m) => ({ default: m.NotesView })),
  files: () => import('@/features/files/FilesView').then((m) => ({ default: m.FilesView })),
  screenshots: () =>
    import('@/features/screenshots/ScreenshotsView').then((m) => ({
      default: m.ScreenshotsView,
    })),
  vault: () => import('@/features/vault/VaultView').then((m) => ({ default: m.VaultView })),
  tools: () => import('@/features/tools/ToolsView').then((m) => ({ default: m.ToolsView })),
  settings: () =>
    import('@/features/settings/SettingsView').then((m) => ({ default: m.SettingsView })),
  profile: () => import('@/features/profile/ProfileView').then((m) => ({ default: m.ProfileView })),
  showcase: () =>
    import('@/features/showcase/ShowcaseView').then((m) => ({ default: m.ShowcaseView })),
  broker: () => import('@/features/broker/BrokerView'),
  debug: () => import('@/features/debug/DebugView').then((m) => ({ default: m.DebugView })),
};

const ChatView = lazy(VIEW_LOADERS.chat);
const PilotView = lazy(VIEW_LOADERS.pilot);
const TasksView = lazy(VIEW_LOADERS.tasks);
const ListsHubView = lazy(VIEW_LOADERS.lists);
const AgendaView = lazy(VIEW_LOADERS.agenda);
const ScrapeView = lazy(VIEW_LOADERS.scrape);
const SavedCapturesView = lazy(VIEW_LOADERS['saved-captures']);
const NeedsYourBrowserView = lazy(VIEW_LOADERS.capture);
const DataView = lazy(VIEW_LOADERS.data);
const HighlightView = lazy(VIEW_LOADERS.highlight);
const GuidanceView = lazy(VIEW_LOADERS.guidance);
const SeoView = lazy(VIEW_LOADERS.seo);
const NotesView = lazy(VIEW_LOADERS.notes);
const FilesView = lazy(VIEW_LOADERS.files);
const ScreenshotsView = lazy(VIEW_LOADERS.screenshots);
const VaultView = lazy(VIEW_LOADERS.vault);
const ToolsView = lazy(VIEW_LOADERS.tools);
const SettingsView = lazy(VIEW_LOADERS.settings);
const ProfileView = lazy(VIEW_LOADERS.profile);
const ShowcaseView = lazy(VIEW_LOADERS.showcase);
const BrokerView = lazy(VIEW_LOADERS.broker);
const DebugView = lazy(VIEW_LOADERS.debug);

const TabFallback = (
  <div className="flex h-full items-center justify-center text-muted-foreground">
    <Loader2 className="size-4 animate-spin" />
  </div>
);

export function App() {
  const theme = useSettingsStore((s) => s.theme);
  const { user, isAdmin } = useAuth();
  const errorCount = useDebugStore((s) => s.events.filter((e) => e.level === 'error').length);
  const tab = useSidepanelTabStore((s) => s.tab);
  const setTab = useSidepanelTabStore((s) => s.setTab);
  const activeTab = useActiveTab();
  const [assistance, setAssistance] = useState<
    'none' | 'saved_login' | 'save_pending' | 'capture_unavailable'
  >('none');
  const [popupCaptureClaimFailed, setPopupCaptureClaimFailed] = useState(false);

  const signedIn = user !== null;
  // The capture-ladder badge. Subscribed at App level so the count is right the
  // first time the person looks, without having opened the tab.
  const needsYou = useNeedsYouCount(signedIn);
  // When the web app hands this browser a page (frontend bridge action
  // `captureHandoff.pickUp`), the panel lands on the capture tab — whether it
  // was already open or is opening because of that call. Acted on ONCE per
  // pointer, so it never fights the person switching tabs afterwards.
  const capturePickup = useCapturePickup();
  const actedPickupAt = useRef<number | null>(null);

  useEffect(() => {
    if (!capturePickup) return;
    if (actedPickupAt.current === capturePickup.at) return;
    actedPickupAt.current = capturePickup.at;
    setTab('capture');
  }, [capturePickup, setTab]);
  const canAccess = (candidate: SidepanelTab) =>
    canAccessSidepanelTab(candidate, { signedIn, isAdmin });

  // A Capture page click in the toolbar asks only to land at Scrape. The
  // intent is session-scoped, expires quickly, and is consumed before routing
  // so reopening the panel cannot repeat it. Watching for the write covers
  // Chromium opening this document before storage.set finishes.
  useEffect(() => {
    let mounted = true;
    const applyPopupIntent = () => {
      void chrome.windows
        .getCurrent()
        .then((window) => {
          if (mounted && window.id != null) {
            const windowId = window.id;
            void waitForSidePanelContextId(windowId).then((contextId) => {
              if (mounted && contextId) {
                void takePopupLaunchTarget(windowId, contextId).then((claim) => {
                  if (!mounted) return;
                  if (claim.status === 'claimed') setTab(claim.target);
                  if (claim.status === 'claim_failed') setPopupCaptureClaimFailed(true);
                });
              }
            });
          }
        })
        .catch(() => undefined);
    };
    const onStorageChanged = (
      changes: Record<string, chrome.storage.StorageChange>,
      areaName: string,
    ) => {
      if (
        areaName === 'session' &&
        Object.entries(changes).some(
          ([key, change]) =>
            key.startsWith(`${POPUP_LAUNCH_INTENT_KEY}.`) && change.newValue !== undefined,
        )
      ) {
        applyPopupIntent();
      }
    };

    applyPopupIntent();
    chrome.storage.onChanged.addListener(onStorageChanged);
    return () => {
      mounted = false;
      chrome.storage.onChanged.removeListener(onStorageChanged);
    };
  }, [setTab]);

  // A persisted tab may become unavailable after sign-out or a release config
  // change. Never render hidden feature content; return to the first public tab.
  useEffect(() => {
    const viewer = { signedIn, isAdmin };
    if (!canAccessSidepanelTab(tab, viewer)) setTab(firstAccessibleSidepanelTab(viewer));
  }, [signedIn, isAdmin, tab, setTab]);

  // Mount ONCE: watches active-tab url and auto-runs every saved pattern that
  // matches. Results land in useAutoExtractStore; DataView reads from there.
  useAutoExtract();

  // Mount ONCE: when the active tab finishes loading and the
  // `scrapeAutoOnLoad` setting is enabled, fast-scrape it in the background
  // and stash in useAutoScrapeStore. The chat hook reads from there on send.
  useAutoScrape();

  // Mount ONCE: listens for SW AGENDA_RUN_NOW broadcasts so auto-mode
  // tasks fire immediately when the sidepanel is open, no click needed.
  useAgendaListener();

  // Mount ONCE: listens for SW PARALLEL_RUN_EVENT broadcasts emitted by
  // the `parallel_for_each_tab` tool. Mirrors lifecycle into the
  // sidepanel-side parallel-runs store so the Tasks tab's panel always
  // has fresh state — even before the user opens that tab.
  useParallelEventBridge();

  // Mount ONCE: listens for the right-click "Ask Matrx about selection"
  // context menu (SW-side) and drains any cold-open pending draft from
  // chrome.storage.session.
  useContextMenuListener();

  // Mount ONCE: owns the Supabase write for highlights captured by the
  // on-page overlay (the page can't reach Supabase) and keeps the highlight
  // store in sync regardless of which tab is active.
  useHighlightBridge();

  // Mount ONCE: on sign-in, hydrate guidance metadata from the cloud
  // (wbx_guidance) into the local cache so guidance follows the user across
  // machines (TASK-004). Writes mirror to the cloud automatically.
  useGuidanceSync();

  // Pre-warm the active tab's chunk. Fires on mount (so the default Chat
  // view is already fetched by the time Suspense reaches it — no flash on
  // sidepanel open) and on every tab change (so the second visit to a tab
  // is instant). Repeat calls hit the browser/Vite import cache; no extra
  // fetch cost.
  useEffect(() => {
    if (canAccessSidepanelTab(tab, { signedIn, isAdmin })) void VIEW_LOADERS[tab]();
  }, [tab, signedIn, isAdmin]);

  // Once-per-mount identity log. Surfaces the runtime extension id +
  // redirect URI in the debug log so any ID drift is visible BEFORE the
  // user clicks Sign in. See .research/v0.1.4-auth-incident.md for why.
  useEffect(() => {
    void import('@/lib/auth/identity').then(({ logExtensionIdentityOnce }) => {
      logExtensionIdentityOnce();
    });
  }, []);

  useEffect(() => {
    const apply = () => {
      const root = document.documentElement;
      const isDark =
        theme === 'dark' ||
        (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
      root.classList.toggle('dark', isDark);
    };
    apply();
    const mql = window.matchMedia('(prefers-color-scheme: dark)');
    mql.addEventListener('change', apply);
    return () => mql.removeEventListener('change', apply);
  }, [theme]);

  useEffect(() => {
    let stale = false;
    let sequence = 0;
    const refresh = () => {
      const request = ++sequence;
      if (activeTab.id === null) {
        setAssistance('none');
        return;
      }
      void send<{ tabId: number }, { state: typeof assistance }>(
        CHANNELS.CREDENTIAL_ASSISTANCE_STATUS,
        { tabId: activeTab.id },
      )
        .then((snapshot) => {
          if (!stale && request === sequence) setAssistance(snapshot.state);
        })
        .catch(() => {
          if (!stale && request === sequence) setAssistance('none');
        });
    };
    refresh();
    const unsubscribe = on<{ tabId: number }, void>(
      CHANNELS.CREDENTIAL_ASSISTANCE_CHANGED,
      (event) => {
        if (event?.tabId === activeTab.id) refresh();
      },
    );
    return () => {
      stale = true;
      unsubscribe();
    };
  }, [activeTab.id]);

  return (
    <TooltipProvider delayDuration={150}>
      {/* THE ONE agent picker. Every surface in this panel that lets a person
          choose an agent renders @ai-matrx/agents/catalog/react beneath this
          provider — same rows, same order, same filters as every other Matrx
          client. `openPeek` is deliberately unbound: the extension has no
          sneak-peek modal, so the package HIDES that affordance rather than
          rendering a dead one. */}
      <AgentCatalogProvider catalog={getAgentCatalog()}>
        {/* Mounted at App root (outside AuthGate) so it overlays every
          surface and works even on auth screens. Renders nothing when
          there's no active prompt; see lib/permissions/gate.ts. */}
        <PermissionPromptModal />
        {/* Database refusals and other "this did not happen" announcements.
          Also at App root, outside AuthGate: a refusal raised while the user
          is on an auth screen still has to be visible. Renders nothing when
          there is no notice; see lib/supabase/db-failure.ts. */}
        <NoticeHost />
        {/* THE ONE confirmation host. Every destructive click in the side
          panel goes through `confirmDestructive()` (src/lib/destructive/),
          which calls the shared `confirm()` opener; that opener needs exactly
          one mounted host to render into. Mounted here, at App root outside
          AuthGate, for the same reason as the two above: a confirmation must
          be able to appear over any surface. Renders nothing until something
          asks. Guarded by tests/unit/destructive-confirm-guard.ts. */}
        <ConfirmDialogHost />
        <div className="flex h-full flex-col bg-background text-foreground">
          <AuthGate>
            <LocalBrowserApprovalHost signedIn={signedIn} />
            <SavedReplayApprovalHost signedIn={signedIn} />
            {popupCaptureClaimFailed && (
              <div
                role="alert"
                className="flex shrink-0 items-center justify-between gap-3 border-b border-destructive/30 bg-destructive/10 px-3 py-2 text-xs text-destructive"
              >
                <span>Capture did not open. Open Scrape to continue.</span>
                <button
                  type="button"
                  className="shrink-0 rounded px-2 py-1 font-medium text-destructive hover:bg-destructive/10"
                  onClick={() => {
                    setTab('scrape');
                    setPopupCaptureClaimFailed(false);
                  }}
                >
                  Open Scrape
                </button>
              </div>
            )}
            <Tabs
              value={tab}
              onValueChange={(v) => setTab(v as typeof tab)}
              className="flex flex-1 flex-col min-h-0"
            >
              <div className="flex shrink-0 items-center gap-1 px-2 py-1.5">
                <TabsList className="flex min-w-0 flex-1 justify-start gap-0.5 overflow-x-auto bg-transparent p-0 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden [&_[role=tab]]:shrink-0">
                  {canAccess('chat') && (
                    <TabsTrigger value="chat" className="size-7 p-0" title="Chat">
                      <MessageSquare className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('pilot') && (
                    <TabsTrigger
                      value="pilot"
                      className="size-7 p-0 data-[state=active]:text-emerald-600 dark:data-[state=active]:text-emerald-400"
                      title="Pilot (admin only — sandboxed tab group)"
                    >
                      <Crosshair className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('lists') && (
                    <TabsTrigger value="lists" className="size-7 p-0" title="Plan & tasks">
                      <ListChecks className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('tasks') && (
                    <TabsTrigger value="tasks" className="size-7 p-0" title="Tasks">
                      <ListTodo className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('agenda') && (
                    <TabsTrigger value="agenda" className="size-7 p-0" title="Agenda">
                      <Calendar className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {/* Capture (Scrape), Patterns (Data), SEO — advertised in the
                    Web Store listing and free to run for guests (no
                    server-agent cost). */}
                  {canAccess('scrape') && (
                    <TabsTrigger value="scrape" className="size-7 p-0" title="Scrape">
                      <ScanLine className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('saved-captures') && (
                    <TabsTrigger
                      value="saved-captures"
                      className="size-7 p-0"
                      title="Saved captures"
                    >
                      <Library className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('capture') && (
                    <TabsTrigger
                      value="capture"
                      className="relative size-7 p-0"
                      aria-label={needsYou.label}
                      title={needsYou.label}
                    >
                      <Inbox className="size-3.5" />
                      {needsYou.count > 0 && (
                        <span className="absolute -right-0.5 -top-0.5 min-w-3.5 rounded-full bg-primary px-0.5 text-[9px] font-semibold leading-3.5 text-primary-foreground">
                          {needsYou.count > 9 ? '9+' : needsYou.count}
                        </span>
                      )}
                    </TabsTrigger>
                  )}
                  {canAccess('data') && (
                    <TabsTrigger value="data" className="size-7 p-0" title="Data">
                      <Database className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('seo') && (
                    <TabsTrigger value="seo" className="size-7 p-0" title="SEO">
                      <Search className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('highlight') && (
                    <TabsTrigger value="highlight" className="size-7 p-0" title="Highlights">
                      <Highlighter className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('guidance') && (
                    <TabsTrigger value="guidance" className="size-7 p-0" title="Guidance">
                      <BookOpen className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('notes') && (
                    <TabsTrigger value="notes" className="size-7 p-0" title="Notes">
                      <NotebookPen className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('files') && (
                    <TabsTrigger value="files" className="size-7 p-0" title="Files">
                      <Files className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('screenshots') && (
                    <TabsTrigger value="screenshots" className="size-7 p-0" title="Screenshots">
                      <Camera className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('vault') && (
                    <TabsTrigger value="vault" className="size-7 p-0" title="Vault">
                      <Vault className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('tools') && (
                    <TabsTrigger value="tools" className="size-7 p-0" title="Tools">
                      <Wrench className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('settings') && (
                    <TabsTrigger value="settings" className="size-7 p-0" title="Settings">
                      <SettingsIcon className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('showcase') && (
                    <TabsTrigger
                      value="showcase"
                      className="size-7 p-0 data-[state=active]:text-violet-600 dark:data-[state=active]:text-violet-400"
                      title="Showcase (admin only)"
                    >
                      <Sparkles className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('broker') && (
                    <TabsTrigger
                      value="broker"
                      className="size-7 p-0 data-[state=active]:text-cyan-600 dark:data-[state=active]:text-cyan-400"
                      title="Token broker (admin only)"
                    >
                      <KeyRound className="size-3.5" />
                    </TabsTrigger>
                  )}
                  {canAccess('debug') && (
                    <TabsTrigger
                      value="debug"
                      className="relative size-7 p-0 data-[state=active]:text-amber-600 dark:data-[state=active]:text-amber-400"
                      title="Debug (admin only)"
                    >
                      <Bug className="size-3.5" />
                      {errorCount > 0 && (
                        <span className="absolute right-0.5 top-0.5 size-1.5 rounded-full bg-red-500" />
                      )}
                    </TabsTrigger>
                  )}
                </TabsList>
                {assistance !== 'none' && tab !== 'vault' && (
                  <button
                    type="button"
                    className="shrink-0 rounded px-1.5 py-1 text-[10px] font-medium text-primary hover:bg-primary/10"
                    title="Open Vault to review saved-login assistance"
                    onClick={() => setTab('vault')}
                  >
                    Open Vault
                  </button>
                )}
                <SiteAccessControl tab={activeTab} />
                <UserMenu />
              </div>
              {/* forceMount (audit P1-14): ChatView owns the live stream-chunk
                listeners and the stall watchdog. Radix unmounts inactive tab
                content by default, so switching sidepanel tabs mid-stream
                dropped every chunk in the gap and orphaned the watchdog
                (which later fired against the new run). Keep the chat
                surfaces mounted; visibility via data-state. */}
              {canAccess('chat') && (
                <TabsContent
                  value="chat"
                  forceMount
                  className="flex-1 min-h-0 data-[state=inactive]:hidden"
                >
                  <Suspense fallback={TabFallback}>
                    <ChatView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('pilot') && (
                <TabsContent
                  value="pilot"
                  forceMount
                  className="flex-1 min-h-0 data-[state=inactive]:hidden"
                >
                  <Suspense fallback={TabFallback}>
                    <PilotView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('lists') && (
                <TabsContent value="lists" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <ListsHubView />
                  </Suspense>
                </TabsContent>
              )}
              {/* forceMount: TasksView's onMessage listener is the ONLY
                receiver for the in-page capture overlay's buttons, and the
                batch-run progress/guard live in component state — Radix
                unmounting it on tab switch bricked the overlay mid-capture
                and let a hidden batch run twice. Same pattern as Chat. */}
              {canAccess('tasks') && (
                <TabsContent
                  value="tasks"
                  forceMount
                  className="flex-1 min-h-0 data-[state=inactive]:hidden"
                >
                  <Suspense fallback={TabFallback}>
                    <TasksView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('agenda') && (
                <TabsContent value="agenda" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <AgendaView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('scrape') && (
                <TabsContent value="scrape" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <ScrapeView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('saved-captures') && (
                <TabsContent value="saved-captures" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <SavedCapturesView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('capture') && (
                <TabsContent value="capture" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <NeedsYourBrowserView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('data') && (
                <TabsContent value="data" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <DataView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('seo') && (
                <TabsContent value="seo" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <SeoView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('highlight') && (
                <TabsContent value="highlight" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <HighlightView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('guidance') && (
                <TabsContent value="guidance" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <GuidanceView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('notes') && (
                <TabsContent value="notes" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <NotesView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('files') && (
                <TabsContent value="files" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <FilesView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('screenshots') && (
                <TabsContent value="screenshots" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <ScreenshotsView />
                  </Suspense>
                </TabsContent>
              )}
              {/* NOT forceMount: unmounting on tab switch is a FEATURE here
                    — it drops any revealed credential held in component state
                    the moment the user leaves the Vault. */}
              {canAccess('vault') && (
                <TabsContent value="vault" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <VaultView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('tools') && (
                <TabsContent value="tools" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <ToolsView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('settings') && (
                <TabsContent value="settings" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <SettingsView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('profile') && (
                <TabsContent value="profile" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <ProfileView />
                  </Suspense>
                </TabsContent>
              )}
              {/* forceMount (audit P1-1): Showcase sub-tabs hold in-progress
                work (network capture buffers, half-built list-pattern
                configs, AI extract results). Leaving and returning must not
                destroy it. Auto-probes are gated on visibility inside
                ShowcaseView, so the mounted-but-hidden tree stays idle. */}
              {canAccess('showcase') && (
                <TabsContent
                  value="showcase"
                  forceMount
                  className="flex-1 min-h-0 data-[state=inactive]:hidden"
                >
                  <Suspense fallback={TabFallback}>
                    <ShowcaseView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('broker') && (
                <TabsContent value="broker" className="flex-1 min-h-0 overflow-y-auto">
                  <Suspense fallback={TabFallback}>
                    <BrokerView />
                  </Suspense>
                </TabsContent>
              )}
              {canAccess('debug') && (
                <TabsContent value="debug" className="flex-1 min-h-0">
                  <Suspense fallback={TabFallback}>
                    <DebugView />
                  </Suspense>
                </TabsContent>
              )}
            </Tabs>
          </AuthGate>
        </div>
      </AgentCatalogProvider>
    </TooltipProvider>
  );
}
