/**
 * `data_patterns` mega-tool — the agent's interface to the saved-extraction
 * system the Showcase + Data tabs drive (audit X3 / decision D8).
 *
 * Actions:
 *   list     (read)   — saved patterns for a domain (default: assigned tab's)
 *   describe (read)   — one pattern's full config/fields
 *   recipes  (read)   — curated recipes matching the assigned tab's URL
 *   run      (action) — execute a saved pattern on the assigned tab
 *                       (DOM kinds in-page; ai_extract via the extractor
 *                       agent; network_capture via guided auto re-capture)
 *   save     (action) — persist a new pattern for the assigned tab's page
 *   delete   (action) — remove a saved pattern
 *
 * Cross-working rule: every action routes through the SAME functions the UI
 * uses (fetchPatternsForDomain / runSavedPattern / savePattern /
 * deletePattern / loadRecipes) — one code path, two drivers.
 *
 * No `description` here (Rule 4) — tool descriptions live ONLY in tool_def.
 */

import { requireRequestOrganizationId } from '@/lib/api/routes/auth';
import { sanitizeNetworkUrl } from '@/lib/credentials/network-urls';
import { urlMatchesPattern } from '@/lib/data-pattern/matcher';
import { loadRecipes, recipesForUrl } from '@/lib/data-pattern/recipes';
import { NetworkNoMatchError, runSavedPattern } from '@/lib/data-pattern/run-interactive';
import { classifySavedRun } from '@/lib/data-pattern/saved-run-outcome';
import {
  type ExtractionPatternField,
  PATTERN_KINDS,
  bumpPatternRun,
  deletePattern,
  fetchPatternsForDomain,
  savePattern,
} from '@/lib/supabase/queries';
import { getAssignedTab } from '@/lib/tools/handlers/_active-tab';
import type { ToolContext, ToolHandler, ToolTier } from '@/lib/tools/types';
import { z } from 'zod';

const FieldSchema = z.object({
  name: z.string().min(1),
  selector: z.string().min(1),
  attr: z.string().optional(),
  is_list: z.boolean().optional(),
});

const DataPatternsArgs = z
  .object({
    action: z.enum(['list', 'describe', 'recipes', 'run', 'save', 'delete']),
    /** For describe / run / delete. */
    pattern_id: z.string().uuid().optional(),
    /** For list — defaults to the assigned tab's host. */
    domain: z.string().optional(),
    /** For save. */
    name: z.string().min(1).max(120).optional(),
    kind: z.enum(PATTERN_KINDS).optional(),
    /** For save — mode-specific config (see the kind's schema). */
    config: z.record(z.string(), z.unknown()).optional(),
    /** For save when kind === 'manual_css'. */
    fields: z.array(FieldSchema).max(40).optional(),
    /** For run — cap on returned rows (full count still reported). */
    rows_limit: z.number().int().min(1).max(500).optional(),
  })
  .superRefine((v, ctx) => {
    if ((v.action === 'describe' || v.action === 'run' || v.action === 'delete') && !v.pattern_id) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `action '${v.action}' requires pattern_id`,
      });
    }
    if (v.action === 'save' && (!v.name || !v.kind)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "action 'save' requires name and kind",
      });
    }
  });
type DataPatternsArgs = z.infer<typeof DataPatternsArgs>;

const preparedPatterns = new WeakMap<
  ToolContext,
  Awaited<ReturnType<typeof fetchPatternsForDomain>>[number]
>();
const preparedPages = new WeakMap<ToolContext, { url: string; documentId: string }>();
const preparedSignals = new WeakMap<ToolContext, AbortSignal>();

const READ_ACTIONS = new Set<DataPatternsArgs['action']>(['list', 'describe', 'recipes']);
const DEFAULT_ROWS_LIMIT = 100;

function hostOf(url: string | undefined): string | null {
  if (!url) return null;
  try {
    return new URL(url).host;
  } catch {
    return null;
  }
}

async function resolveDomain(
  args: DataPatternsArgs,
  ctx: Parameters<ToolHandler<DataPatternsArgs, unknown>['run']>[1],
): Promise<string | null> {
  if (args.domain) return args.domain;
  const tab = await getAssignedTab(ctx);
  return hostOf(tab?.url ?? undefined);
}

export const data_patterns: ToolHandler<DataPatternsArgs, unknown> = {
  name: 'data_patterns',
  tier: 'action',
  tierFor: (args): ToolTier => (READ_ACTIONS.has(args.action) ? 'read' : 'action'),
  argsSchema: DataPatternsArgs,
  prepare: async (args, ctx) => {
    if (args.action !== 'run') return null;
    const tab = await getAssignedTab(ctx);
    if (tab?.id == null || !tab.url) throw new Error('No assigned page to run on.');
    const patterns = await fetchPatternsForDomain(new URL(tab.url).host);
    const pattern = patterns.find((p) => p.id === args.pattern_id);
    if (!pattern) throw new Error('The saved pattern no longer exists on this site.');
    if (pattern.kind !== 'network_capture') return null;
    const [{ documentId } = {}] = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: () => null,
    });
    if (!documentId)
      throw new Error(
        'Chrome did not provide source document identity. Run again in a supported Chrome version.',
      );
    const bytes = new TextEncoder().encode(
      JSON.stringify([
        pattern.id,
        pattern.kind,
        pattern.config,
        pattern.fields,
        pattern.list_root_selector,
        tab.id,
        tab.url,
        documentId,
      ]),
    );
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    const snapshotKey = Array.from(new Uint8Array(digest), (b) =>
      b.toString(16).padStart(2, '0'),
    ).join('');
    // Read capability policy from the existing canonical handler, not its approval identity.
    const { cdp_attach } = await import('./cdp');
    return {
      snapshotKey,
      tier: 'privileged',
      approvalPreview: {
        kind: 'saved-network-replay',
        recipeName: pattern.name,
        pageUrl: sanitizeNetworkUrl(tab.url),
      },
      requirements: {
        ...(cdp_attach.admin_only !== undefined && { admin_only: cdp_attach.admin_only }),
        ...(cdp_attach.required_optional_permissions && {
          required_optional_permissions: cdp_attach.required_optional_permissions,
        }),
        ...(cdp_attach.supportedBrowsers && { supportedBrowsers: cdp_attach.supportedBrowsers }),
      },
      run: async (signal) => {
        preparedPatterns.set(ctx, pattern);
        preparedSignals.set(ctx, signal);
        preparedPages.set(ctx, { url: tab.url!, documentId });
        try {
          return await data_patterns.run(args, ctx);
        } finally {
          preparedPatterns.delete(ctx);
          preparedSignals.delete(ctx);
          preparedPages.delete(ctx);
        }
      },
    };
  },
  run: async (args, ctx) => {
    if (args.action === 'list') {
      const domain = await resolveDomain(args, ctx);
      if (!domain) return { ok: false, reason: 'No domain — pass one or open a normal page.' };
      const patterns = await fetchPatternsForDomain(domain);
      return {
        ok: true,
        domain,
        patterns: patterns.map((p) => ({
          id: p.id,
          name: p.name,
          kind: p.kind,
          route_pattern: p.route_pattern,
          field_count: p.fields.length,
          last_status: p.last_status,
          last_run_at: p.last_run_at,
          last_run_count: p.last_run_count,
        })),
      };
    }

    if (args.action === 'describe') {
      const domain = await resolveDomain(args, ctx);
      if (!domain) return { ok: false, reason: 'No domain to look in.' };
      const patterns = await fetchPatternsForDomain(domain);
      const pattern = patterns.find((p) => p.id === args.pattern_id);
      if (!pattern) {
        return { ok: false, reason: `No pattern ${args.pattern_id} under ${domain}.` };
      }
      return { ok: true, pattern };
    }

    if (args.action === 'recipes') {
      const tab = await getAssignedTab(ctx);
      if (!tab?.url) return { ok: false, reason: 'No assigned tab URL.' };
      const all = await loadRecipes();
      const matching = recipesForUrl(tab.url, all);
      return {
        ok: true,
        url: tab.url,
        matching,
        total_in_catalog: all.length,
      };
    }

    if (args.action === 'run') {
      const tab = await getAssignedTab(ctx);
      if (!tab?.id) return { ok: false, reason: 'No assigned tab to run on.' };
      const tabId = tab.id;
      const domain = hostOf(tab.url ?? undefined);
      if (!domain) return { ok: false, reason: 'Assigned tab has no usable URL.' };
      const prepared = preparedPatterns.get(ctx);
      const patterns = prepared ? [prepared] : await fetchPatternsForDomain(domain);
      const pattern = patterns.find((p) => p.id === args.pattern_id);
      if (!pattern) {
        return { ok: false, reason: `No pattern ${args.pattern_id} under ${domain}.` };
      }
      if (pattern.kind === 'network_capture' && !prepared) {
        return { ok: false, reason: 'Network replay requires the saved-run approval dispatcher.' };
      }
      // Ordinary DOM and framework runs must start on a proven top-frame
      // document. Network replay intentionally owns its own reload contract.
      let documentId: string | null = null;
      if (pattern.kind !== 'network_capture') {
        try {
          const frame = await chrome.webNavigation.getFrame({ tabId, frameId: 0 });
          if (!frame?.documentId || frame.errorOccurred || frame.url !== tab.url) {
            return {
              ok: false,
              reason:
                'The assigned page identity is unavailable. Reload it and run the pattern again.',
              retryable: true,
            };
          }
          documentId = frame.documentId;
        } catch {
          return {
            ok: false,
            reason: 'Could not verify the assigned page. Reload it and run the pattern again.',
            retryable: true,
          };
        }
      }
      const pageIsCurrent = async () => {
        try {
          const current = await chrome.tabs.get(tabId);
          if (current.url !== tab.url) return false;
          if (documentId) {
            const frame = await chrome.webNavigation.getFrame({ tabId, frameId: 0 });
            return frame?.documentId === documentId && !frame.errorOccurred;
          }
          return true;
        } catch {
          return false;
        }
      };
      const pageChanged = {
        ok: false,
        reason:
          'The assigned page changed or closed during extraction. Run the saved pattern again on the intended page.',
        retryable: true,
      };
      try {
        if (!(await pageIsCurrent())) return pageChanged;
        const replayEvidence: { documentId: string | null } = { documentId: null };
        // 'auto': an AGENT called this tool. The person's gesture was the
        // parent chat send, already attested there; this nested AI run is the
        // model's decision, not a second human action.
        const rows = await runSavedPattern(pattern, tabId, {
          onProgress: (note) => ctx.reportProgress?.(note),
          onReplayDocument: (id) => {
            replayEvidence.documentId = id;
          },
          initiation: ctx.localInvocation ? 'user' : 'auto',
          ...(documentId && { documentId }),
          ...(prepared && {
            captureApproved: true,
            signal: preparedSignals.get(ctx)!,
            expectedPage: preparedPages.get(ctx)!,
          }),
        });
        if (!(await pageIsCurrent())) return pageChanged;
        const replayFrame =
          pattern.kind === 'network_capture' && ctx.localInvocation
            ? await chrome.webNavigation.getFrame({ tabId, frameId: 0 })
            : null;
        if (
          pattern.kind === 'network_capture' &&
          ctx.localInvocation &&
          (!replayEvidence.documentId ||
            replayFrame?.documentId !== replayEvidence.documentId ||
            replayFrame.errorOccurred ||
            replayFrame.url !== tab.url)
        )
          return pageChanged;
        const outcome = classifySavedRun(pattern, tab.url ?? '', rows);
        const updateError =
          !ctx.localInvocation && outcome.kind === 'matched'
            ? await bumpPatternRun(pattern.id, 'ok', rows.length)
            : null;
        const limit = ctx.localInvocation ? rows.length : (args.rows_limit ?? DEFAULT_ROWS_LIMIT);
        return {
          ok: true,
          outcome: outcome.kind,
          ...(outcome.message && { message: outcome.message }),
          ...(updateError && {
            warning: `Rows were extracted, but saved run history could not be updated: ${updateError}`,
          }),
          pattern: { id: pattern.id, name: pattern.name, kind: pattern.kind },
          row_count: rows.length,
          rows: rows.slice(0, limit),
          truncated: rows.length > limit,
          ...(replayEvidence.documentId &&
            ctx.localInvocation && {
              replay_document_id: replayEvidence.documentId,
            }),
        };
      } catch (err) {
        if (!(await pageIsCurrent())) return pageChanged;
        if (err instanceof NetworkNoMatchError) {
          // Circumstantial, not a broken pattern — give the agent guidance.
          return { ok: false, reason: err.message, retryable: true };
        }
        const updateError =
          !ctx.localInvocation && urlMatchesPattern(tab.url ?? '', pattern)
            ? await bumpPatternRun(pattern.id, 'broken', 0)
            : null;
        return {
          ok: false,
          reason: err instanceof Error ? err.message : String(err),
          ...(updateError && { warning: `Saved run history could not be updated: ${updateError}` }),
        };
      }
    }

    if (args.action === 'save') {
      const tab = await getAssignedTab(ctx);
      const domain = args.domain ?? hostOf(tab?.url ?? undefined);
      if (!domain) return { ok: false, reason: 'No domain — pass one or open a normal page.' };
      let route: string | null = null;
      try {
        route = tab?.url ? new URL(tab.url).pathname : null;
      } catch {
        route = null;
      }
      const saved = await savePattern({
        // DD-131: the model's turn is what produced this pattern, so the write
        // rides the agent-authored client and declares `x-matrx-actor-tier: agent`.
        authored_by: 'agent',
        organization_id: await requireRequestOrganizationId(),
        name: args.name as string,
        domain,
        route_pattern: route,
        list_root_selector: null,
        fields: (args.fields ?? []) as ExtractionPatternField[],
        ...(args.kind !== undefined && { kind: args.kind }),
        config: args.config ?? {},
        target_user_table_id: null,
      });
      if (!saved) return { ok: false, reason: 'Save failed — check connection and inputs.' };
      return { ok: true, id: saved.id, domain };
    }

    if (args.action === 'delete') {
      // DD-131: the model asked for this deletion, not the person.
      const ok = await deletePattern(args.pattern_id as string, 'agent');
      return ok ? { ok: true, deleted: args.pattern_id } : { ok: false, reason: 'Delete failed.' };
    }

    return { ok: false, reason: `Unknown action: ${args.action as string}` };
  },
};

export const data_pattern_handlers = [data_patterns];
